const approvalRepository = require('../repositories/approvalRepository');

function validateDecision(body) {
  const { payPeriodId, decision, approvedBy, comment = '' } = body;
  if (!payPeriodId || !['approved', 'rejected'].includes(decision) || !approvedBy?.trim()) {
    return { error: 'VALIDATION_ERROR', message: 'payPeriodId, a valid decision, and approvedBy are required.' };
  }
  if (decision === 'rejected' && !comment.trim()) {
    return { error: 'COMMENT_REQUIRED', message: 'A comment is required to reject.' };
  }
  return null;
}

async function submitDecision(body) {
  const validationError = validateDecision(body);
  if (validationError) return validationError;
  return approvalRepository.recordDecision({
    payPeriodId: body.payPeriodId,
    decision: body.decision,
    approvedBy: body.approvedBy.trim(),
    comment: body.comment?.trim(),
  });
}

module.exports = { ...approvalRepository, submitDecision };

