import { useState, useEffect } from 'react';
import './ApprovalPage.css';

const API_URL = '/api/approvals';
const money = new Intl.NumberFormat('en-SG', { style: 'currency', currency: 'SGD' });

function ApprovalPage() {
  const [periods, setPeriods] = useState([]);
  const [periodId, setPeriodId] = useState('');
  const [summary, setSummary] = useState(null);
  const [selectedLine, setSelectedLine] = useState(null);
  const [message, setMessage] = useState(null);
  const [decision, setDecision] = useState('approved');
  const [manager, setManager] = useState('Managing Director');
  const [comment, setComment] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadPeriods();
  }, []);

  useEffect(() => {
    if (periodId) loadSummary(periodId);
  }, [periodId]);

  async function request(url, options) {
    const res = await fetch(url, options);
    const data = await res.json();
    if (!res.ok) throw new Error(data.message || 'Something went wrong.');
    return data;
  }

  async function loadPeriods() {
    try {
      setLoading(true);
      const data = await request(`${API_URL}/periods`);
      setPeriods(data);
      if (data.length) setPeriodId(data.find((period) => period.status === 'pending_approval')?.id || data[0].id);
    } catch (error) {
      setMessage({ type: 'error', text: `Could not load payroll periods: ${error.message}` });
    } finally { setLoading(false); }
  }

  async function loadSummary(id = periodId) {
    try {
      setLoading(true);
      setSummary(await request(`${API_URL}/summary?payPeriodId=${id}`));
    } catch (error) {
      setMessage({ type: 'error', text: `Could not load payroll summary: ${error.message}` });
    } finally { setLoading(false); }
  }

  async function showLine(lineId) {
    try { setSelectedLine(await request(`${API_URL}/lines/${lineId}`)); }
    catch (error) { setMessage({ type: 'error', text: error.message }); }
  }

  async function submitDecision(event) {
    event.preventDefault();
    try {
      const result = await request(API_URL, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ payPeriodId: periodId, decision, approvedBy: manager, comment }),
      });
      setMessage({ type: 'success', text: decision === 'approved'
        ? `Payroll approved by ${result.approvedBy} and locked for payment.`
        : 'Payroll rejected and returned to Pending Calculation with your feedback.' });
      setComment('');
      await Promise.all([loadSummary(), loadPeriods()]);
    } catch (error) { setMessage({ type: 'error', text: error.message }); }
  }

  return (
    <main className="approval-page">
      <header><p className="eyebrow">UC-004 · Manager Workspace</p><h1>Review & approve payroll</h1><p>Review calculated pay, inspect an employee line, then record your decision.</p></header>
      {message && <div className={`message ${message.type}`}>{message.text}</div>}
      <section className="toolbar"><label>Payroll cycle<select value={periodId} onChange={(e) => setPeriodId(e.target.value)}>{periods.map((p) => <option key={p.id} value={p.id}>{p.startDate} to {p.endDate} · {p.status.replace('_', ' ')}</option>)}</select></label></section>
      {loading && <p>Loading payroll information…</p>}
      {summary && <>
        <section className="cards">
          <article><span>Total gross</span><strong>{money.format(summary.totalGross)}</strong></article>
          <article><span>Total net</span><strong>{money.format(summary.totalNet)}</strong></article>
          <article><span>Previous cycle net</span><strong>{summary.previousCycle.totalNet ? money.format(summary.previousCycle.totalNet) : 'No previous cycle'}</strong></article>
          <article><span>Current status</span><strong className={`status ${summary.status}`}>{summary.status.replace('_', ' ')}</strong></article>
        </section>
        <section className="panel"><h2>Employee payroll breakdown</h2><p>Click “View details” to inspect hours and performance inputs.</p>
        <table>
        <thead>
          <tr>
            <th>Employee</th>
            <th>Gross Pay</th>
            <th>Incentive</th>
            <th>CPF</th>
            <th>SDL</th>
            <th>Net Pay</th>
            <th>Status</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {summary.lines.map((line) => (
            <tr key={line.id}><td>{line.fullName}</td><td>{money.format(line.grossPay)}</td><td>{money.format(line.incentivePay)}</td><td>{money.format(line.cpfAmount)}</td><td>{money.format(line.sdlAmount)}</td><td>{money.format(line.netPay)}</td><td><span className={`status ${line.status}`}>{line.status}</span></td><td><button className="secondary" onClick={() => showLine(line.id)}>View details</button></td>
            </tr>
          ))}
        </tbody>
        </table></section>
        {summary.status === 'pending_approval' && <section className="panel decision"><h2>Record decision</h2><form onSubmit={submitDecision}><label>Manager name<input value={manager} onChange={(e) => setManager(e.target.value)} required /></label><label>Decision<select value={decision} onChange={(e) => setDecision(e.target.value)}><option value="approved">Approve payroll</option><option value="rejected">Reject payroll</option></select></label>{decision === 'rejected' && <label>Reason for rejection<textarea value={comment} onChange={(e) => setComment(e.target.value)} required placeholder="Explain what needs to be corrected" /></label>}<button type="submit" className={decision === 'approved' ? 'approve' : 'reject'}>{decision === 'approved' ? 'Approve and lock payroll' : 'Reject and return for calculation'}</button></form></section>}
      </>}
      {selectedLine && <div className="modal-backdrop" onClick={() => setSelectedLine(null)}><section className="modal" onClick={(e) => e.stopPropagation()}><button className="close" onClick={() => setSelectedLine(null)}>×</button><h2>{selectedLine.fullName}</h2><p>{selectedLine.employmentType.replace('_', ' ')}</p><div className="details"><span>Hours</span><b>{selectedLine.totalHours || 0}</b><span>Overtime hours</span><b>{selectedLine.otHours || 0}</b><span>Public-holiday hours</span><b>{selectedLine.phHours || 0}</b><span>Gross + incentive</span><b>{money.format(Number(selectedLine.grossPay) + Number(selectedLine.incentivePay))}</b><span>Deductions (CPF + SDL)</span><b>{money.format(Number(selectedLine.cpfAmount) + Number(selectedLine.sdlAmount))}</b><span>Net pay</span><b>{money.format(selectedLine.netPay)}</b></div><h3>Performance inputs</h3>{selectedLine.performanceInputs.length ? <ul>{selectedLine.performanceInputs.map((item) => <li key={item.metricType}>{item.metricType}: {item.metricValue}</li>)}</ul> : <p>No performance inputs required for this employee.</p>}</section></div>}
    </main>
  );
}

export default ApprovalPage;

