const pool = require('../db');

async function listPayPeriods() {
  const { rows } = await pool.query(`
    SELECT id, start_date AS "startDate", end_date AS "endDate", status,
           total_gross AS "totalGross", total_net AS "totalNet", locked_at AS "lockedAt"
    FROM pay_period
    ORDER BY start_date DESC`);
  return rows;
}

async function getSummary(payPeriodId) {
  const { rows } = await pool.query(`
    WITH selected_period AS (
      SELECT * FROM pay_period WHERE id = $1
    ), previous_period AS (
      SELECT total_net FROM pay_period
      WHERE end_date < (SELECT start_date FROM selected_period)
        AND status = 'approved'
      ORDER BY end_date DESC LIMIT 1
    )
    SELECT p.id AS "payPeriodId", p.start_date AS "startDate", p.end_date AS "endDate",
           p.status, p.total_gross AS "totalGross", p.total_net AS "totalNet",
           p.locked_at AS "lockedAt", (SELECT total_net FROM previous_period) AS "previousTotalNet",
           COALESCE(json_agg(json_build_object(
             'id', pl.id, 'staffId', s.id, 'fullName', s.full_name,
             'grossPay', pl.gross_pay, 'incentivePay', pl.incentive_pay,
             'cpfAmount', pl.cpf_amount, 'sdlAmount', pl.sdl_amount,
             'deductions', pl.cpf_amount + pl.sdl_amount, 'netPay', pl.net_pay,
             'status', pl.status
           ) ORDER BY s.full_name) FILTER (WHERE pl.id IS NOT NULL), '[]') AS lines
    FROM selected_period p
    LEFT JOIN payroll_line pl ON pl.pay_period_id = p.id
    LEFT JOIN staff s ON s.id = pl.staff_id
    GROUP BY p.id, p.start_date, p.end_date, p.status, p.total_gross, p.total_net, p.locked_at`, [payPeriodId]);
  return rows[0] || null;
}

async function getLineDetail(lineId) {
  const { rows } = await pool.query(`
    SELECT pl.id, s.full_name AS "fullName", s.employment_type AS "employmentType",
           pl.gross_pay AS "grossPay", pl.incentive_pay AS "incentivePay",
           pl.cpf_amount AS "cpfAmount", pl.sdl_amount AS "sdlAmount", pl.net_pay AS "netPay",
           pl.status, t.total_hours AS "totalHours", t.ot_hours AS "otHours", t.ph_hours AS "phHours",
           COALESCE((SELECT json_agg(json_build_object('metricType', metric_type, 'metricValue', metric_value))
                     FROM performance_input pi
                     WHERE pi.pay_period_id = pl.pay_period_id AND pi.staff_id = pl.staff_id), '[]') AS "performanceInputs"
    FROM payroll_line pl
    JOIN staff s ON s.id = pl.staff_id
    LEFT JOIN timesheet t ON t.pay_period_id = pl.pay_period_id AND t.staff_id = pl.staff_id
    WHERE pl.id = $1`, [lineId]);
  return rows[0] || null;
}

async function recordDecision({ payPeriodId, decision, approvedBy, comment }) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const periodResult = await client.query(
      'SELECT id, status FROM pay_period WHERE id = $1 FOR UPDATE', [payPeriodId]);
    const period = periodResult.rows[0];
    if (!period) { await client.query('ROLLBACK'); return { error: 'NOT_FOUND' }; }
    if (period.status !== 'pending_approval') { await client.query('ROLLBACK'); return { error: 'INVALID_STATUS', status: period.status }; }

    const incomplete = await client.query(
      "SELECT 1 FROM payroll_line WHERE pay_period_id = $1 AND status = 'incomplete' LIMIT 1", [payPeriodId]);
    if (incomplete.rowCount) { await client.query('ROLLBACK'); return { error: 'INCOMPLETE_LINES' }; }

    const newStatus = decision === 'approved' ? 'approved' : 'pending_calculation';
    const updateResult = await client.query(`
      UPDATE pay_period
      SET status = $2::varchar, locked_at = CASE WHEN $2::varchar = 'approved' THEN now() ELSE NULL END, updated_at = now()
      WHERE id = $1
      RETURNING id AS "payPeriodId", status, locked_at AS "lockedAt"`, [payPeriodId, newStatus]);
    const updated = updateResult.rows[0];
    const approvalResult = await client.query(`
      INSERT INTO approval (pay_period_id, decision, approved_by, comment)
      VALUES ($1, $2, $3, $4)
      RETURNING approved_by AS "approvedBy", decided_at AS "decidedAt"`,
      [payPeriodId, decision, approvedBy, comment || null]);
    const approval = approvalResult.rows[0];
    await client.query(`
      INSERT INTO audit_log (entity_type, entity_id, action, actor, detail)
      VALUES ('pay_period', $1, $2, $3, $4::jsonb)`,
      [payPeriodId, decision, approvedBy, JSON.stringify({ comment: comment || null, resultingStatus: newStatus })]);
    await client.query('COMMIT');
    return { ...updated, ...approval, decision, locked: decision === 'approved' };
  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  } finally {
    client.release();
  }
}

module.exports = { listPayPeriods, getSummary, getLineDetail, recordDecision };

